def is_polite(num):
    if num < 3:
        return False
    for k in range(1, int(math.sqrt(2 * num)) + 1):
        if (k * (k + 1)) % 2 == 0 and (k * (k + 1) // 2) <= num and (num - (k * (k + 1) // 2)) % k == 0:
            return True
    return False

def nth_polite_number(n):
    if n == 1:
        return 3
    k = 1
    while True:
        polite = k * (k + 1) // 2
        if polite >= n:
            return polite
        k += 1

